// The immutable source is transferred once per document. Computations never mutate live state.
export class TaskClient {
 constructor(){this.worker=new Worker(new URL('./task-worker.js',import.meta.url),{type:'module'});this.pending=new Map();this.keys=new WeakMap();this.serial=0;this.worker.onmessage=({data})=>{const job=this.pending.get(data.id);if(!job)return;this.pending.delete(data.id);clearTimeout(job.timer);data.error?job.reject(Error(data.error)):job.resolve({result:data.result,workerMs:Math.round(data.ms)});};this.worker.onerror=()=>{for(const job of this.pending.values()){clearTimeout(job.timer);job.reject(Error('背景工作失敗，請重新載入工作台'));}this.pending.clear();};}
 run(task,project,extra={}){const id=++this.serial,transfer=[],message={id,task,...extra};if(project){const {source,...rest}=project;message.project=rest;let key=this.keys.get(source);if(!key){key='source-'+id;this.keys.set(source,key);const pixels=Uint8Array.from(source.pixels);message.source={width:source.width,height:source.height,pixels};transfer.push(pixels.buffer);}message.sourceKey=key;}
 return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{this.pending.delete(id);reject(Error('背景工作逾時，未提交；請 inspect 後再操作'));},120000);this.pending.set(id,{resolve,reject,timer});this.worker.postMessage(message,transfer);});}
 forget(source){const key=this.keys.get(source);if(key)this.worker.postMessage({task:'drop',sourceKey:key});this.keys.delete(source);}
}
export function commitTask(workspace,id,revision,project,summary,dryRun){const d=workspace.get(id);if(d.revision!==revision)throw Error('背景工作完成時文件已變動，結果已捨棄，請重新預演');if(!dryRun){const e=d.engine;e.history.push(e.snapshot());e.history=e.history.slice(-32);while(e.history.length>1&&e.history.reduce((n,s)=>n+s.width*s.height*4*s.layers.length,0)>8_388_608)e.history.shift();e.future=[];e.project={...project,source:e.project.source};workspace.touch(id);}return {...summary,revision:d.revision,dryRun};}
